-- Verified Megastudy booklet tables, 2012–2016 academic years. Existing edits take precedence.
begin;
create temp table pdf_rates(academic_year integer,section text, question_no integer, rate numeric,level text,source_url text,basis text, primary key(academic_year,section,question_no)) on commit drop;
create temp table matched_rates on commit drop as
select p.id as problem_id, q.variant, r.*
from pdf_rates r join public.exam_sessions s on s.academic_year=r.academic_year and s.kind='csat' and s.provider='kice' and s.grade='고3'
join public.exam_questions q on (q.session_id,q.section,q.question_no)=(s.id,r.section,r.question_no) and q.variant in ('odd','even')
join public.problems p on p.exam_question_id=q.id and p.public and not p.withdrawn;
do $$begin
if (select count(*) from matched_rates)<>600 or exists(
 select 1 from matched_rates group by academic_year,section,question_no
 having count(*)<>2 or count(distinct variant)<>2)
then raise exception 'CATALOG_CHANGED_REVIEW_REQUIRED'; end if;
end$$;
select problem_id,level,'correct_rate',rate,basis,source_url,'2026-11-24T08:30:41.293Z'::timestamptz,'megastudy-20-50-80-v1'
from matched_rates
on conflict(problem_id) do nothing;
do $$begin
if exists(select 1 from matched_rates m left join public.problem_difficulties d using(problem_id) where d.problem_id is null)
then raise exception 'RATES_INCOMPLETE'; end if;
end$$;
select m.variant,m.level,count(*) as matched,
 count(*) filter(where d.problem_id is null) as missing,
 count(*) filter(where (m.level,m.rate,m.source_url)=(d.level,d.correct_rate,d.source_url)) as imported,
 count(*) filter(where d.classification_method='manual') as manual
from matched_rates m left join public.problem_difficulties d using(problem_id)
group by m.variant,m.level order by m.variant,m.level;
commit;
